var HelpRotiniMcp = "`rotini-mcp` serves the tool definitions a rotini program's tools feature writes (tools/mcp.json) as an MCP server on stdio, running the program for each call, and adds that server to MCP clients' configuration.\n\nUsage:\n  rotini-mcp [flags] <command>\n\nCommands:\n  serve      serve a tools file over MCP on stdio\n  config     add, remove or list servers in an MCP client's configuration\n  help       print help\n  version    print version\n\nFlags:\n  -h, --help       print help\n      --version    print version\n\nUse \"rotini-mcp help <command>\" for more information about a command."

var HelpRotiniMcpServe = "Serve the tools in a tools file over MCP on stdio. Each call runs the program with the command line its arguments make, in the server's environment, and returns what it prints.\n\nUsage:\n  rotini-mcp serve [flags]\n\nFlags:\n      --tools string             the tools file Rotini's tools feature writes (required)\n      --bin string               the program to run for each call (required)\n      --env []string             a variable to add to the program's environment (KEY=value) (repeatable)\n      --tool []string            serve only this tool (repeatable)\n      --timeout duration         stop a call that runs longer than this (0 for no limit) (default 0s)\n      --grace duration           how long a stopped call has between SIGTERM and being killed (0 kills it at once) (default 5s)\n      --output-limit bytesize    the most output a call may write on each of stdout and stderr (default 10Mi)\n      --concurrency int          run at most this many calls at once; more wait their turn (0 for no limit) (default 0)\n      --revision string          the MCP revision to serve the tools for (default 2026-07-28) [2026-07-28|2025-11-25]\n\nGlobal Flags:\n  -h, --help       print help\n      --version    print version\n\nExamples:\n  rotini-mcp serve --tools tools/mcp.json --bin ./taskr"

var HelpRotiniMcpConfig = "Add, remove or list MCP servers in an MCP client's configuration file. A file is backed up to <file>.bak before it is rewritten, replacing an earlier backup. The rewrite keeps every other setting, but comments are not kept.\n\nUsage:\n  rotini-mcp config <command>\n\nCommands:\n  enable     add a server to a client's configuration\n  disable    remove a server from a client's configuration\n  list       list the servers in a client's configuration\n\nGlobal Flags:\n  -h, --help       print help\n      --version    print version"

var HelpRotiniMcpConfigEnable = "Add a server to a client's configuration. With --tools and --bin, the client runs rotini-mcp serve for that program; with --command, it runs that command (such as a program that serves its own tools). The entry names this rotini-mcp executable, so run an installed rotini-mcp, not one from go run. --env values are written into the client's file, which for a project's file is often committed; keep secrets out of them. A --command or --bin path is written as an absolute path. A server already in the file keeps its other settings. The file is backed up to <file>.bak, and comments in it are not kept.\n\nUsage:\n  rotini-mcp config enable [flags] <client> <name>\n\nArguments:\n  <client>    the client [claude-desktop|claude-code|cursor|vscode]\n  <name>      the server's name in the client\n\nFlags:\n      --tools string      the tools file to serve\n      --bin string        the program to run for each call; a path, or a name on PATH\n      --command string    the command the client runs instead of rotini-mcp serve\n      --arg []string      an argument for --command (repeatable)\n      --env []string      a variable the client sets for the server (KEY=value) (repeatable)\n      --scope string      the user's file or the project's (by default the client's first) [user|project]\n\nGlobal Flags:\n  -h, --help       print help\n      --version    print version\n\nExamples:\n  rotini-mcp config enable claude-desktop taskr --tools tools/mcp.json --bin ./taskr\n  rotini-mcp config enable cursor taskr --command taskr --arg mcp"

var HelpRotiniMcpConfigDisable = "Remove a server from a client's configuration. The file is backed up to <file>.bak, and comments in it are not kept.\n\nUsage:\n  rotini-mcp config disable [flags] <client> <name>\n\nArguments:\n  <client>    the client [claude-desktop|claude-code|cursor|vscode]\n  <name>      the server's name in the client\n\nFlags:\n      --scope string    the user's file or the project's (by default the client's first) [user|project]\n\nGlobal Flags:\n  -h, --help       print help\n      --version    print version"

var HelpRotiniMcpConfigList = "list the servers in a client's configuration\n\nUsage:\n  rotini-mcp config list [flags] <client>\n\nArguments:\n  <client>    the client [claude-desktop|claude-code|cursor|vscode]\n\nFlags:\n      --scope string    the user's file or the project's (by default the client's first) [user|project]\n\nGlobal Flags:\n  -h, --help       print help\n      --version    print version"

